// ---- helpers (shared by the workflows in this pack) ----
const cfg = $('Config').first().json;
const zone = cfg.timezone || 'UTC';
const now = DateTime.now().setZone(zone);
const today = now.startOf('day');

// Read the first non-empty value among several possible column names.
const val = (row, ...keys) => {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return '';
};

// Accepts 2026-11-20, 2026-11-20T14:30, 11/20/2026, 20.11.2026, Nov 20, 2026 or a Sheets serial number.
function parseDate(v) {
  if (v === undefined || v === null || v === '') return null;
  if (typeof v === 'number') {
    return DateTime.fromMillis(Math.round((v - 25569) * 86400000), { zone: 'utc' })
      .setZone(zone, { keepLocalTime: true });
  }
  const s = String(v).trim();
  let d = DateTime.fromISO(s, { zone });
  if (d.isValid) return d;
  d = DateTime.fromSQL(s, { zone });
  if (d.isValid) return d;
  for (const f of ['M/d/yyyy', 'M/d/yyyy H:mm', 'M/d/yyyy h:mm a', 'M/d/yy', 'd.M.yyyy', 'yyyy/M/d', 'd MMM yyyy', 'MMM d, yyyy', 'MMMM d, yyyy']) {
    d = DateTime.fromFormat(s, f, { zone });
    if (d.isValid) return d;
  }
  const js = new Date(s);
  return isNaN(js) ? null : DateTime.fromJSDate(js).setZone(zone);
}

// Whole days between a date and today (positive = in the past).
const daysAgo = (d) => Math.round(today.diff(d.startOf('day'), 'days').days);

const firstName = (name) => (String(name || '').trim().split(/\s+/)[0] || 'there');

const toNumber = (v) => {
  if (typeof v === 'number') return v;
  const n = parseFloat(String(v ?? '').replace(/[^0-9.\-]/g, ''));
  return isNaN(n) ? 0 : n;
};

function money(amount, currency) {
  const cur = (currency || cfg.currency || 'USD').toUpperCase();
  try {
    return new Intl.NumberFormat(cfg.locale || 'en-US', { style: 'currency', currency: cur }).format(toNumber(amount));
  } catch (e) {
    return cur + ' ' + toNumber(amount).toFixed(2);
  }
}

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

const button = (url, label) => url
  ? `<p style="margin:24px 0"><a href="${esc(url)}" style="background:${cfg.brandColor || '#2563eb'};color:#ffffff;padding:12px 22px;border-radius:6px;text-decoration:none;font-weight:bold;display:inline-block">${esc(label)}</a></p>`
  : '';

// Wraps body HTML in a clean, mobile-friendly email layout.
const layout = (inner) => `<div style="font-family:Arial,Helvetica,sans-serif;font-size:15px;line-height:1.6;color:#1f2937;max-width:560px;margin:0 auto;padding:24px">${inner}<p style="margin-top:32px;color:#6b7280;font-size:13px">${esc(cfg.businessName || '')}</p></div>`;
// ---- end helpers ----

const sales = $input.all()
  .map((i) => i.json)
  .map((r) => ({ d: parseDate(r['Date']), amount: toNumber(r['Amount']), who: val(r, 'Customer Name', 'Customer Email') || 'Customer', order: val(r, 'Order ID') }))
  .filter((s) => s.d);

const on = (day) => sales.filter((s) => s.d.hasSame(day, 'day'));
const sum = (list) => list.reduce((t, s) => t + s.amount, 0);
const pct = (a, b) => (b ? Math.round(((a - b) / b) * 100) : null);
const arrow = (p) => (p === null ? '' : p >= 0 ? ` <span style="color:#16a34a">▲ ${p}%</span>` : ` <span style="color:#dc2626">▼ ${Math.abs(p)}%</span>`);

const todays = on(today);
const yesterday = on(today.minus({ days: 1 }));
const lastWeek = on(today.minus({ days: 7 }));
const mtd = sales.filter((s) => s.d.hasSame(today, 'month') && s.d <= now);

if (!todays.length && cfg.skipIfNoSales) return [];

const total = sum(todays);
const tile = (label, value, extra = '') => `<td style="padding:12px;border:1px solid #e5e7eb;border-radius:6px;text-align:center"><div style="font-size:12px;color:#6b7280;text-transform:uppercase">${label}</div><div style="font-size:22px;font-weight:bold">${value}</div><div style="font-size:12px">${extra}</div></td>`;
const rows = todays
  .sort((a, b) => b.amount - a.amount)
  .slice(0, 25)
  .map((s) => `<tr><td style="padding:6px;border-bottom:1px solid #f3f4f6">${s.d.toFormat('HH:mm')}</td><td style="padding:6px;border-bottom:1px solid #f3f4f6">${esc(s.who)}</td><td style="padding:6px;border-bottom:1px solid #f3f4f6;text-align:right">${money(s.amount)}</td></tr>`)
  .join('');

const html = layout(`
  <h2 style="margin:0 0 4px">Sales for ${today.toFormat('cccc d LLLL')}</h2>
  <p style="margin:0 0 16px;color:#6b7280">Your end-of-day snapshot</p>
  <table style="width:100%;border-collapse:separate;border-spacing:8px"><tr>
    ${tile('Revenue', money(total), 'vs yesterday' + arrow(pct(total, sum(yesterday))))}
    ${tile('Orders', todays.length, 'vs yesterday' + arrow(pct(todays.length, yesterday.length)))}
    ${tile('Avg order', money(todays.length ? total / todays.length : 0))}
  </tr></table>
  <p>Same day last week: <b>${money(sum(lastWeek))}</b> (${lastWeek.length} orders)${arrow(pct(total, sum(lastWeek)))}<br>
  Month to date: <b>${money(sum(mtd))}</b> from ${mtd.length} orders</p>
  ${rows ? `<h3>Today's orders</h3><table style="width:100%;border-collapse:collapse;font-size:14px">${rows}</table>` : '<p>No sales recorded today.</p>'}
`);
return [{ json: { subject: `${cfg.businessName}: ${money(total)} from ${todays.length} order${todays.length === 1 ? '' : 's'} today`, html } }];
